import { useMemo, useState, type FormEvent, type ReactNode } from 'react'
import { Link, NavLink, Navigate, Route, Routes, useNavigate, useParams } from 'react-router-dom'
import { Area, AreaChart, Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { toast } from 'sonner'
import {
  Award, Banknote, Bell, BookOpen, BriefcaseBusiness, Building2, Check, CheckCircle2, ChevronDown,
  ChevronLeft, ChevronRight, CircleAlert, ClipboardCheck, Clock3, Download, FileText, Filter, GraduationCap,
  LayoutDashboard, ListChecks, LogOut, Menu, MonitorPlay, MoreHorizontal, Play, Plus, Printer, Search,
  ShieldCheck, SignalLow, SlidersHorizontal, Sparkles, Upload, UserRound, Users, WifiOff, X,
} from 'lucide-react'
import { courses, getTenantCourses, metrics, tenants, users } from './data'
import { useDemo, useTenant } from './store'
import type { Assignment, Certificate, Course, DemoRole, LessonVideo, ProgressRecord } from './types'
import { Badge, Button, Card, Dialog, PageTitle, Progress, Tabs, TabsContent, TabsList, TabsTrigger, cn, inputClass } from './ui'

const fmtDate = (value: string) => new Intl.DateTimeFormat('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(`${value}T00:00:00`))

function Logo({ compact = false }: { compact?: boolean }) {
  const tenant = useTenant()
  return <div className="flex items-center gap-3"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[var(--tenant-dark)] font-bold text-white shadow-sm">{tenant.initials}</div>{!compact && <div><p className="font-bold leading-tight text-slate-950">{tenant.name}</p><p className="text-xs text-slate-500">Learning workspace</p></div>}</div>
}

function SignIn() {
  const { enterWorkspace } = useDemo()
  const [tenantId, setTenantId] = useState<'acacia' | 'highland'>('acacia')
  const [role, setRole] = useState<DemoRole>('learner')
  const selected = tenants.find((tenant) => tenant.id === tenantId)!
  const navigate = useNavigate()
  const enter = () => { enterWorkspace(tenantId, role); navigate(role === 'learner' ? '/learn' : '/admin') }

  return <main className="min-h-screen bg-[#f5f7f3]">
    <section className="flex min-h-screen items-center justify-center p-5 sm:p-10">
      <div className="w-full max-w-2xl">
        <div className="mb-10 flex items-center justify-between gap-4"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#355b28] text-white"><GraduationCap size={22} /></div><div><p className="font-bold leading-tight text-slate-950">Banking Learning Hub</p><p className="text-xs text-slate-500">Demo environment</p></div></div><a href="/" className="flex shrink-0 items-center gap-1 whitespace-nowrap text-sm font-semibold text-[#50783d] hover:underline"><ChevronLeft size={16} />Back to site</a></div>
        <p className="text-xs font-bold uppercase tracking-[.18em] text-[#50783d]">Choose your demo workspace</p><h2 className="mt-2 text-3xl font-bold tracking-tight text-slate-950">Enter the learning platform</h2><p className="mt-3 text-sm leading-6 text-slate-600">Select a fictional bank and role. In production, employees enter through their bank’s SSO.</p>
        <div className="mt-8 grid gap-3 sm:grid-cols-2">{tenants.map((tenant) => <button key={tenant.id} onClick={() => setTenantId(tenant.id)} className={cn('rounded-xl border-2 bg-white p-5 text-left transition hover:border-slate-300', tenantId === tenant.id ? 'border-[var(--tenant-accent)] shadow-sm' : 'border-slate-200')} style={{ '--tenant-accent': tenant.accent } as React.CSSProperties}><div className="flex items-center justify-between"><div className="grid h-11 w-11 place-items-center rounded-xl font-bold text-white" style={{ background: tenant.dark }}>{tenant.initials}</div>{tenantId === tenant.id && <div className="grid h-6 w-6 place-items-center rounded-full text-white" style={{ background: tenant.dark }}><Check size={15} /></div>}</div><p className="mt-5 font-bold text-slate-950">{tenant.name}</p><p className="mt-1 text-xs leading-5 text-slate-500">{tenant.tagline}</p></button>)}</div>
        <fieldset className="mt-7"><legend className="text-sm font-bold text-slate-800">Demo role</legend><div className="mt-3 grid gap-3 sm:grid-cols-2">{([{ id: 'learner', label: 'Employee learner', detail: 'Take courses and earn certificates', icon: UserRound }, { id: 'admin', label: 'HR administrator', detail: 'Assign learning and review results', icon: BriefcaseBusiness }] as const).map((item) => <label key={item.id} className={cn('flex cursor-pointer items-start gap-3 rounded-xl border bg-white p-4', role === item.id ? 'border-slate-500' : 'border-slate-200')}><input className="mt-1 accent-[#355b28]" type="radio" name="role" value={item.id} checked={role === item.id} onChange={() => setRole(item.id)} /><item.icon className="mt-0.5 text-slate-600" size={20} /><span><span className="block text-sm font-bold text-slate-900">{item.label}</span><span className="mt-1 block text-xs text-slate-500">{item.detail}</span></span></label>)}</div></fieldset>
        <Button size="lg" className="mt-7 w-full" onClick={enter} style={{ '--tenant-dark': selected.dark } as React.CSSProperties}>Enter {selected.shortName} workspace <ChevronRight size={18} /></Button>
        <div className="mt-7 grid gap-3 text-xs text-slate-500 sm:grid-cols-2"><p className="flex gap-2"><ShieldCheck size={16} className="shrink-0 text-slate-600" />SSO would identify the employee, bank, and role.</p><p className="flex gap-2"><WifiOff size={16} className="shrink-0 text-slate-600" />Designed for local hosting and constrained connectivity.</p></div>
      </div>
    </section>
  </main>
}

const learnerNav = [{ to: '/learn', label: 'Home', icon: LayoutDashboard }, { to: '/learn/my-learning', label: 'My Learning', icon: BookOpen }, { to: '/learn/catalogue', label: 'Course Catalogue', icon: Search }, { to: '/learn/certificates', label: 'Certificates', icon: Award }]
const adminNav = [{ to: '/admin', label: 'Overview', icon: LayoutDashboard }, { to: '/admin/employees', label: 'Employees', icon: Users }, { to: '/admin/assignments', label: 'Learning Assignments', icon: ListChecks }, { to: '/admin/reports', label: 'Reports', icon: FileText }]

function Shell({ children }: { children: ReactNode }) {
  const demo = useDemo(); const tenant = useTenant(); const navigate = useNavigate(); const [mobileOpen, setMobileOpen] = useState(false)
  const nav = demo.role === 'learner' ? learnerNav : adminNav
  const switchRole = (role: DemoRole) => { demo.switchRole(role); navigate(role === 'learner' ? '/learn' : '/admin') }
  return <div className="min-h-screen bg-[#f6f7f4]" style={{ '--tenant-accent': tenant.accent, '--tenant-dark': tenant.dark } as React.CSSProperties}>
    <header className="sticky top-0 z-40 flex h-16 items-center border-b border-slate-200 bg-white px-4 sm:px-7 lg:ml-[274px] lg:w-[calc(100%_-_274px)] lg:px-9">
      <button onClick={() => setMobileOpen(true)} aria-label="Open navigation" className="mr-3 rounded-md p-2 text-slate-600 hover:bg-slate-100 lg:hidden"><Menu /></button>
      <div className="flex min-w-0 flex-1 items-center justify-between gap-4"><div className="min-w-0"><p className="truncate text-sm font-bold text-slate-900">{tenant.name} {demo.role === 'learner' ? 'Learning' : 'HR Administration'}</p></div><div className="flex items-center gap-2"><button aria-label="Notifications" className="relative rounded-lg p-2 text-slate-600 hover:bg-slate-100"><Bell size={20} /><span className="absolute right-1 top-1 h-2 w-2 rounded-full bg-red-500 ring-2 ring-white" /></button><div className="group relative"><button className="flex items-center gap-2 rounded-lg border border-slate-200 py-1.5 pl-2 pr-3 hover:bg-slate-50"><div className="grid h-8 w-8 place-items-center rounded-lg bg-slate-100 text-xs font-bold text-slate-700">{demo.currentUser?.name.split(' ').map((part) => part[0]).join('')}</div><span className="hidden text-left sm:block"><span className="block text-xs font-bold text-slate-900">{demo.currentUser?.name}</span><span className="block text-[11px] text-slate-500">{demo.currentUser?.jobTitle}</span></span><ChevronDown size={15} className="text-slate-500" /></button><div className="invisible absolute right-0 top-full z-50 mt-2 w-64 translate-y-1 rounded-xl border border-slate-200 bg-white p-2 opacity-0 shadow-xl transition group-focus-within:visible group-focus-within:translate-y-0 group-focus-within:opacity-100 group-hover:visible group-hover:translate-y-0 group-hover:opacity-100"><p className="px-3 py-2 text-xs font-bold uppercase tracking-wider text-slate-400">Switch demo role</p><button onClick={() => switchRole('learner')} className="flex w-full items-center gap-3 rounded-lg px-3 py-2 text-left text-sm hover:bg-slate-50"><UserRound size={17} />Employee learner{demo.role === 'learner' && <Check size={15} className="ml-auto" />}</button><button onClick={() => switchRole('admin')} className="flex w-full items-center gap-3 rounded-lg px-3 py-2 text-left text-sm hover:bg-slate-50"><BriefcaseBusiness size={17} />HR administrator{demo.role === 'admin' && <Check size={15} className="ml-auto" />}</button><div className="my-2 border-t border-slate-100" /><button onClick={() => { demo.signOut(); navigate('/') }} className="flex w-full items-center gap-3 rounded-lg px-3 py-2 text-left text-sm text-red-700 hover:bg-red-50"><LogOut size={17} />Leave workspace</button></div></div></div></div>
    </header>
    <aside className={cn('fixed inset-y-0 left-0 z-50 w-[274px] border-r border-slate-200 bg-white p-5 transition-transform lg:translate-x-0', mobileOpen ? 'translate-x-0' : '-translate-x-full')}><div className="flex items-center justify-between"><Logo /><button aria-label="Close navigation" onClick={() => setMobileOpen(false)} className="rounded-md p-1.5 text-slate-500 hover:bg-slate-100 lg:hidden"><X /></button></div><nav className="mt-9 space-y-1">{nav.map((item) => <NavLink end={item.to === '/learn' || item.to === '/admin'} key={item.to} to={item.to} onClick={() => setMobileOpen(false)} className={({ isActive }) => cn('flex items-center gap-3 rounded-[10px] px-3.5 py-3 text-sm font-semibold transition', isActive ? 'bg-[color-mix(in_srgb,var(--tenant-accent)_15%,white)] text-[var(--tenant-dark)]' : 'text-slate-600 hover:bg-slate-50')}><item.icon size={19} />{item.label}</NavLink>)}</nav><div className="absolute bottom-5 left-5 right-5 rounded-xl bg-[#f4f8f1] p-4"><div className="flex items-center gap-2 text-xs font-bold text-[var(--tenant-dark)]"><Building2 size={16} />Private bank workspace</div><p className="mt-2 text-xs leading-5 text-slate-600">Only {tenant.shortName} employees, courses, and results are visible.</p></div></aside>
    {mobileOpen && <button className="fixed inset-0 z-40 bg-slate-950/40 lg:hidden" aria-label="Close navigation" onClick={() => setMobileOpen(false)} />}
    <main className="px-4 py-7 sm:px-7 lg:ml-[274px] lg:px-9 lg:py-9"><div className="mx-auto max-w-[1320px]">{children}</div></main>
  </div>
}

function Protected({ children }: { children: ReactNode }) { const { signedIn } = useDemo(); return signedIn ? <Shell>{children}</Shell> : <Navigate to="/" replace /> }

function GroupedList({ children, className }: { children: ReactNode; className?: string }) {
  return <div className={cn('divide-y divide-slate-200 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-[0_1px_2px_rgba(15,23,42,.04)]', className)}>{children}</div>
}

function CourseListItem({ course, progressRecord, assignment }: { course: Course; progressRecord?: ProgressRecord; assignment?: Assignment }) {
  const showProgress = Boolean(progressRecord || assignment)
  const percent = progressRecord?.percent ?? 0
  return <Link to={`/learn/courses/${course.id}`} aria-label={`Open ${course.title}`} className="group grid cursor-pointer gap-5 p-5 transition-colors hover:bg-slate-50 focus-visible:relative focus-visible:z-10 lg:grid-cols-[minmax(0,1fr)_220px_32px] lg:items-center">
    <div className="min-w-0">
      {!assignment && <div className="flex flex-wrap items-center gap-2"><Badge tone={course.tenantId ? 'amber' : 'green'}>{course.tenantId ? 'Your bank’s content' : 'Shared curriculum'}</Badge>{course.languages.map((language) => <Badge key={language}>{language}</Badge>)}</div>}
      <h3 className={cn('text-base font-bold leading-6 text-slate-950 sm:text-lg', !assignment && 'mt-3')}>{course.title}</h3>
      {!assignment && <p className="mt-1 line-clamp-1 text-sm leading-6 text-slate-600">{course.description}</p>}
      <div className="mt-2 flex flex-wrap items-center gap-4 text-xs text-slate-500"><span className="flex items-center gap-1.5"><Clock3 size={15} />{course.duration} min</span><span>{course.category}</span><span>{course.required ? 'Required' : 'Optional'}</span>{assignment?.dueDate && <span>Due {fmtDate(assignment.dueDate)}</span>}</div>
    </div>
    <div>
      {showProgress ? <><div className="mb-2 flex justify-between text-xs text-slate-500"><span className="font-semibold">Progress</span><span>{percent}%</span></div><Progress value={percent} /></> : <p className="text-xs leading-5 text-slate-500">{course.modules.length} modules<br />Pass mark {course.passMark}%</p>}
    </div>
    <ChevronRight aria-hidden="true" className="self-center text-[var(--tenant-dark)] transition-transform group-hover:translate-x-1" size={20} />
  </Link>

  /* Grid card retained for a possible future revert:
  return <Card className="group flex h-full flex-col overflow-hidden"><div className="h-1.5 bg-[var(--tenant-accent)]" /><div className="flex flex-1 flex-col p-5"><div className="flex items-start justify-between gap-3"><Badge tone={course.tenantId ? 'amber' : 'green'}>{course.tenantId ? 'Your bank’s content' : 'Shared curriculum'}</Badge><div className="flex gap-1">{course.languages.map((language) => <Badge key={language}>{language}</Badge>)}</div></div><h3 className="mt-4 text-lg font-bold leading-6 text-slate-950">{course.title}</h3><p className="mt-2 line-clamp-2 text-sm leading-6 text-slate-600">{course.description}</p><div className="mt-5 flex items-center gap-4 text-xs text-slate-500"><span className="flex items-center gap-1.5"><Clock3 size={15} />{course.duration} min</span><span>{course.category}</span></div>{progress > 0 && <div className="mt-5"><div className="mb-2 flex justify-between text-xs"><span className="font-semibold text-slate-700">Progress</span><span>{progress}%</span></div><Progress value={progress} /></div>}<Link to={`/learn/courses/${course.id}`} className="mt-5 inline-flex items-center gap-1 text-sm font-bold text-[var(--tenant-dark)] hover:underline">{progress ? 'Continue course' : 'View course'} <ChevronRight size={16} /></Link></div></Card>
  */
}

function LearnerHome() {
  const demo = useDemo(); const tenant = useTenant(); const tenantCourses = getTenantCourses(tenant.id); const learnerProgress = demo.progress.filter((p) => p.tenantId === tenant.id && p.userId === demo.currentUser?.id); const active = learnerProgress.find((p) => p.status === 'In progress'); const activeCourse = tenantCourses.find((c) => c.id === active?.courseId) ?? tenantCourses[0]; const assigned = demo.assignments.filter((a) => a.tenantId === tenant.id).slice(0, 3)
  return <><PageTitle compact title={`Good morning, ${demo.currentUser?.name.split(' ')[0]}`} description={`${demo.currentUser?.jobTitle} · ${demo.currentUser?.branch}`} />
    <Card className="relative overflow-hidden bg-[var(--tenant-dark)] text-white"><div className="absolute right-0 top-0 h-full w-1/3 bg-[radial-gradient(circle_at_center,rgba(255,255,255,.13),transparent_62%)]" /><div className="relative grid gap-7 p-6 sm:p-8 md:grid-cols-[1fr_auto] md:items-center"><div><Badge className="bg-white/10 text-white">Continue learning</Badge><h2 className="mt-4 text-2xl font-bold">{activeCourse.title}</h2><p className="mt-2 max-w-xl text-sm leading-6 text-white/70">Pick up where you left off. Your progress is stored in this demo workspace.</p><div className="mt-5 max-w-lg"><div className="mb-2 flex justify-between text-xs"><span>{active?.percent ?? 0}% complete</span><span>{activeCourse.duration} minutes</span></div><Progress value={active?.percent ?? 0} className="bg-white/20" /></div></div><Link to={`/learn/courses/${activeCourse.id}/player`}><Button variant="secondary" size="lg"><Play size={18} fill="currentColor" />Resume course</Button></Link></div></Card>
    <section className="mt-8"><div className="mb-4 flex items-end justify-between"><div><h2 className="text-xl font-bold text-slate-950">Required learning</h2><p className="mt-1 text-sm text-slate-500">Courses assigned by your learning team</p></div><Link className="text-sm font-bold text-[var(--tenant-dark)]" to="/learn/my-learning">View all</Link></div><GroupedList>{assigned.map((assignment) => { const course = tenantCourses.find((c) => c.id === assignment.courseId)!; const record = learnerProgress.find((p) => p.courseId === course.id); return <CourseListItem key={assignment.id} course={course} progressRecord={record} assignment={assignment} /> })}</GroupedList></section>
    <section className="mt-8"><h2 className="text-xl font-bold">Recommended for your role</h2><GroupedList className="mt-4"><CourseListItem course={tenantCourses.find((c) => c.id === 'service')!} /><CourseListItem course={tenantCourses.find((c) => c.id === 'cyber')!} /></GroupedList></section>
    <section className="mt-8"><h2 className="text-xl font-bold">Your certificate</h2><Link to="/learn/certificates" className="group mt-4 flex cursor-pointer flex-col gap-5 rounded-xl border border-slate-200 bg-white p-5 shadow-[0_1px_2px_rgba(15,23,42,.04)] transition-colors hover:bg-slate-50 sm:flex-row sm:items-center sm:p-6"><div className="grid h-12 w-12 shrink-0 place-items-center rounded-xl bg-amber-100 text-amber-700"><Award /></div><div className="min-w-0 flex-1"><div className="flex items-baseline gap-3"><p className="text-3xl font-bold">{demo.certificates.filter((c) => c.userId === demo.currentUser?.id).length}</p><p className="text-sm font-semibold text-slate-700">Certificate earned</p></div><p className="mt-1 text-sm leading-6 text-slate-500">Your certificates remain available in this workspace.</p></div><ChevronRight className="shrink-0 text-[var(--tenant-dark)] transition-transform group-hover:translate-x-1" size={20} /></Link></section>
  </>
}

function MyLearning() {
  const demo = useDemo(); const tenant = useTenant(); const tenantCourses = getTenantCourses(tenant.id); const records = demo.progress.filter((p) => p.tenantId === tenant.id && p.userId === demo.currentUser?.id); const tenantAssignments = demo.assignments.filter((assignment) => assignment.tenantId === tenant.id)
  const courseList = (status?: string) => <GroupedList>{tenantCourses.filter((course) => { const record = records.find((p) => p.courseId === course.id); return !status || status === 'Required' ? (status ? course.required : true) : record?.status === status }).map((course) => <CourseListItem key={course.id} course={course} progressRecord={records.find((p) => p.courseId === course.id)} assignment={tenantAssignments.find((assignment) => assignment.courseId === course.id)} />)}</GroupedList>
  return <><PageTitle eyebrow="Learner portal" title="My learning" description="Track assigned, active, and completed learning." /><Tabs defaultValue="In progress"><TabsList className="mb-5 flex w-full overflow-x-auto sm:w-auto"><TabsTrigger value="In progress">In progress</TabsTrigger><TabsTrigger value="Required">Required</TabsTrigger><TabsTrigger value="Completed">Completed</TabsTrigger></TabsList><TabsContent value="In progress">{courseList('In progress')}</TabsContent><TabsContent value="Required">{courseList('Required')}</TabsContent><TabsContent value="Completed">{courseList('Completed')}</TabsContent></Tabs></>
}

function Catalogue() {
  const tenant = useTenant(); const [search, setSearch] = useState(''); const [category, setCategory] = useState('All'); const [language, setLanguage] = useState('All');
  const filtered = getTenantCourses(tenant.id).filter((course) => course.title.toLowerCase().includes(search.toLowerCase()) && (category === 'All' || course.category === category) && (language === 'All' || course.languages.includes(language as 'EN' | 'AM')))
  return <><PageTitle eyebrow="Learner portal" title="Course catalogue" description="Explore shared banking curriculum and content from your bank." /><Card className="mb-6 p-4"><div className="grid gap-3 md:grid-cols-[1fr_220px_160px]"><label className="relative"><span className="sr-only">Search courses</span><Search className="absolute left-3 top-3 text-slate-400" size={19} /><input className={cn(inputClass, 'pl-10')} placeholder="Search by course title" value={search} onChange={(e) => setSearch(e.target.value)} /></label><select aria-label="Filter by category" className={inputClass} value={category} onChange={(e) => setCategory(e.target.value)}><option>All</option>{['Compliance', 'Credit', 'Risk', 'Customer Service', 'Onboarding', 'Digital Banking'].map((item) => <option key={item}>{item}</option>)}</select><select aria-label="Filter by language" className={inputClass} value={language} onChange={(e) => setLanguage(e.target.value)}><option>All</option><option>EN</option><option>AM</option></select></div></Card>{filtered.length ? <GroupedList>{filtered.map((course) => <CourseListItem key={course.id} course={course} />)}</GroupedList> : <EmptyState icon={Search} title="No matching courses" body="Try clearing a filter or using a different search term." action={<Button variant="outline" onClick={() => { setSearch(''); setCategory('All'); setLanguage('All') }}>Clear filters</Button>} />}</>
}

function CourseDetails() {
  const { courseId } = useParams(); const demo = useDemo(); const tenant = useTenant(); const course = getTenantCourses(tenant.id).find((item) => item.id === courseId); const navigate = useNavigate(); if (!course) return <Navigate to="/learn/catalogue" replace />; const record = demo.progress.find((p) => p.userId === demo.currentUser?.id && p.courseId === course.id)
  const percent = record?.percent ?? 0
  return <>
    <div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
      <button onClick={() => navigate(-1)} className="flex items-center gap-1 text-sm font-bold text-slate-600 hover:text-slate-900"><ChevronLeft size={17} />Back</button>
      <div className="flex flex-wrap gap-2">
        <Badge tone={course.tenantId ? 'amber' : 'green'}>{course.tenantId ? 'Your bank’s policy content' : 'Shared banking curriculum'}</Badge>
        {course.languages.map((language) => <Badge key={language}>{language}</Badge>)}
      </div>
    </div>
    <Card className="overflow-hidden">
      <section className="border-b border-slate-200 p-5 sm:p-7 lg:p-9">
        <div className="grid gap-7 lg:grid-cols-[220px_1fr] lg:items-stretch">
          <div className="grid min-h-48 place-items-center rounded-xl bg-[color-mix(in_srgb,var(--tenant-accent)_17%,white)] lg:h-full lg:min-h-0">
            <div className="text-center text-[var(--tenant-dark)]">
              <MonitorPlay className="mx-auto" size={48} />
              <p className="mt-4 text-xs font-bold uppercase tracking-[.16em]">{course.category}</p>
            </div>
          </div>
          <div className="min-w-0">
            <h1 className="max-w-4xl text-3xl font-bold tracking-tight text-slate-950 sm:text-4xl">{course.title}</h1>
            <p className="mt-4 max-w-3xl text-base leading-7 text-slate-600">{course.description}</p>
            <div className="mt-6 flex flex-wrap gap-x-6 gap-y-3 text-sm text-slate-600">
              <span className="flex items-center gap-2"><Clock3 size={18} />{course.duration} minutes</span>
              <span className="flex items-center gap-2"><Users size={18} />{course.audience}</span>
              <span className="flex items-center gap-2"><ClipboardCheck size={18} />Pass mark {course.passMark}%</span>
            </div>
          </div>
        </div>
        <div className="mt-7 w-full rounded-xl bg-slate-50 p-4 sm:p-5">
          <div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
            <div className="min-w-0 flex-1">
              <div className="flex items-center justify-between gap-4">
                <p className="font-bold text-slate-900">{record?.status ?? 'Ready to begin'}</p>
                <p className="text-sm font-semibold text-slate-500">{percent}% complete</p>
              </div>
              <Progress value={percent} className="mt-3" />
            </div>
            <Link className="shrink-0" to={`/learn/courses/${course.id}/player`}>
              <Button className="w-full sm:w-auto">{percent ? 'Continue course' : 'Start course'}<ChevronRight size={17} /></Button>
            </Link>
          </div>
          <p className="mt-4 text-xs leading-5 text-slate-500">Passing the assessment creates a certificate in this demo workspace.</p>
        </div>
      </section>
      <section className="p-5 sm:p-7 lg:p-9">
        <h2 className="text-xl font-bold">What you will learn</h2>
        <ul className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-3">
          {course.objectives.map((item) => <li key={item} className="flex gap-3 rounded-xl border border-slate-200 bg-slate-50/60 p-4 text-sm leading-6 text-slate-700"><CheckCircle2 className="mt-0.5 shrink-0 text-[var(--tenant-dark)]" size={19} />{item}</li>)}
        </ul>
        <div className="mt-9 border-t border-slate-200 pt-8">
          <div className="flex items-end justify-between gap-4">
            <div><h2 className="text-xl font-bold">Course content</h2><p className="mt-1 text-sm text-slate-500">{course.modules.length} modules · {course.duration} minutes</p></div>
            <Badge tone={record?.status === 'Completed' ? 'green' : 'neutral'}>{record?.status ?? 'Not started'}</Badge>
          </div>
          <div className="mt-4 divide-y divide-slate-100 rounded-xl border border-slate-200">
            {course.modules.map((module, index) => <div key={module.id} className="flex items-center gap-4 p-4 sm:px-5"><div className={cn('grid h-9 w-9 shrink-0 place-items-center rounded-lg text-xs font-bold', record?.completedModuleIds.includes(module.id) ? 'bg-emerald-100 text-emerald-800' : 'bg-slate-100 text-slate-600')}>{record?.completedModuleIds.includes(module.id) ? <Check size={16} /> : index + 1}</div><div className="min-w-0 flex-1"><p className="font-semibold text-slate-900">{module.title}</p><p className="mt-1 text-xs text-slate-500">{module.kind === 'assessment' ? 'Assessment' : 'Lesson'} · {module.duration} min{module.video ? ' · Video' : ''}</p></div>{record?.completedModuleIds.includes(module.id) && <CheckCircle2 className="text-emerald-600" size={20} />}</div>)}
          </div>
        </div>
      </section>
    </Card>
  </>
}

// Nothing is requested from YouTube until the learner presses play.
function LessonVideoPlayer({ video }: { video: LessonVideo }) {
  const [playing, setPlaying] = useState(false)
  const minutes = Math.floor(video.seconds / 60); const seconds = String(video.seconds % 60).padStart(2, '0')
  return <div>
    {playing
      ? <iframe className="aspect-video w-full rounded-2xl bg-black" src={`https://www.youtube-nocookie.com/embed/${video.youtubeId}?autoplay=1&rel=0&modestbranding=1`} title={video.title} allow="autoplay; encrypted-media; picture-in-picture; fullscreen" referrerPolicy="strict-origin-when-cross-origin" />
      : <button type="button" onClick={() => setPlaying(true)} aria-label={`Play video: ${video.title}`} className="group grid aspect-video w-full place-items-center rounded-2xl bg-[#273f21] p-6 text-center text-white focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--tenant-dark)]">
        <span><span className="mx-auto grid h-16 w-16 place-items-center rounded-full bg-white/15 transition group-hover:bg-white/25"><Play fill="white" /></span><span className="mt-4 block text-sm font-semibold">{video.title}</span><span className="mt-1 block text-xs text-white/60">{minutes}:{seconds} · Plays from YouTube when you press play</span></span>
      </button>}
    <p className="mt-3 text-xs leading-5 text-slate-500">Video: {video.title}, {video.author}. Third-party video shown for demonstration. <a className="font-semibold text-[var(--tenant-dark)] underline" href={`https://www.youtube.com/watch?v=${video.youtubeId}`} target="_blank" rel="noreferrer">Video not loading? Open on YouTube</a></p>
  </div>
}

function CoursePlayer() {
  const { courseId } = useParams(); const tenant = useTenant(); const demo = useDemo(); const navigate = useNavigate(); const course = getTenantCourses(tenant.id).find((item) => item.id === courseId); const [moduleIndex, setModuleIndex] = useState(0); const [drawer, setDrawer] = useState(false); if (!course) return <Navigate to="/learn/catalogue" replace />; const module = course.modules[moduleIndex]; const record = demo.progress.find((p) => p.userId === demo.currentUser?.id && p.courseId === course.id); const goNext = () => { if (module.kind === 'assessment') navigate(`/learn/courses/${course.id}/assessment`); else { demo.markModuleComplete(course.id, module.id, course.modules.length); toast.success('Lesson progress saved'); if (moduleIndex < course.modules.length - 1) setModuleIndex(moduleIndex + 1) } }
  const moduleNav = <div>{course.modules.map((item, index) => <button key={item.id} onClick={() => { setModuleIndex(index); setDrawer(false) }} className={cn('flex w-full items-start gap-3 rounded-lg p-3 text-left', index === moduleIndex ? 'bg-[color-mix(in_srgb,var(--tenant-accent)_14%,white)]' : 'hover:bg-slate-50')}><span className={cn('grid h-7 w-7 shrink-0 place-items-center rounded-full border text-xs font-bold', record?.completedModuleIds.includes(item.id) ? 'border-emerald-600 bg-emerald-600 text-white' : index === moduleIndex ? 'border-[var(--tenant-dark)] text-[var(--tenant-dark)]' : 'border-slate-300 text-slate-500')}>{record?.completedModuleIds.includes(item.id) ? <Check size={14} /> : index + 1}</span><span><span className="block text-sm font-semibold text-slate-900">{item.title}</span><span className="mt-1 block text-xs text-slate-500">{item.duration} min</span></span></button>)}</div>
  return <div className="-mx-4 -my-7 sm:-mx-7 lg:-mx-9 lg:-my-9"><div className="flex h-16 items-center justify-between border-b border-slate-200 bg-white px-4 sm:px-6"><div className="flex min-w-0 items-center gap-3"><button aria-label="Back to course" onClick={() => navigate(`/learn/courses/${course.id}`)} className="rounded-md p-2 hover:bg-slate-100"><X size={20} /></button><div className="min-w-0"><p className="truncate text-sm font-bold">{course.title}</p><p className="text-xs text-slate-500">Module {moduleIndex + 1} of {course.modules.length}</p></div></div><div className="flex items-center gap-3"><label className="hidden items-center gap-2 text-xs font-semibold text-slate-600 sm:flex"><input type="checkbox" checked={demo.lowBandwidth} onChange={(e) => demo.setLowBandwidth(e.target.checked)} className="accent-[var(--tenant-dark)]" />Low bandwidth</label><Badge tone="green">{record?.percent ?? 0}% complete</Badge><button className="rounded-md p-2 lg:hidden" onClick={() => setDrawer(true)}><Menu /></button></div></div><div className="grid min-h-[calc(100vh-8rem)] lg:grid-cols-[290px_1fr]"><aside className="hidden border-r border-slate-200 bg-white p-4 lg:block"><p className="mb-4 px-3 text-xs font-bold uppercase tracking-wider text-slate-400">Course content</p>{moduleNav}</aside><div className="bg-[#f6f7f4] p-4 sm:p-8 lg:p-12"><div className="mx-auto max-w-3xl"><div className="flex items-center gap-2 text-xs font-bold uppercase tracking-wider text-[var(--tenant-dark)]">{module.kind === 'assessment' ? <ClipboardCheck size={16} /> : <BookOpen size={16} />}{module.kind}</div><h1 className="mt-3 text-3xl font-bold tracking-tight text-slate-950">{module.title}</h1>{module.kind === 'assessment' ? <Card className="mt-7 p-7 text-center"><ClipboardCheck className="mx-auto text-[var(--tenant-dark)]" size={40} /><h2 className="mt-4 text-xl font-bold">Ready for the knowledge check?</h2><p className="mx-auto mt-2 max-w-lg text-sm leading-6 text-slate-600">Answer five questions. You need {course.passMark}% to complete this course and receive a certificate.</p><Button className="mt-6" onClick={() => navigate(`/learn/courses/${course.id}/assessment`)}>Start assessment</Button></Card> : <><div className="mt-7">{demo.lowBandwidth ? <div className="flex items-start gap-3 rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900"><SignalLow className="shrink-0" size={20} /><div><p className="font-bold">Low bandwidth mode is on</p><p className="mt-1 leading-5">Media is hidden. Lesson text and progress remain available on this device.</p></div></div> : module.video ? <LessonVideoPlayer key={module.id} video={module.video} /> : <div className="grid aspect-video place-items-center rounded-2xl bg-[#273f21] text-white"><div className="text-center"><div className="mx-auto grid h-16 w-16 place-items-center rounded-full bg-white/15"><Play fill="white" /></div><p className="mt-4 text-sm font-semibold">Lesson media preview</p><p className="mt-1 text-xs text-white/60">No external media is loaded</p></div></div>}</div><Card className="mt-6 p-6 sm:p-8"><p className="text-xs font-bold uppercase tracking-wider text-slate-400">Lesson reading</p>{module.content.map((paragraph) => <p key={paragraph} className="mt-4 text-[15px] leading-7 text-slate-700">{paragraph}</p>)}<div className="mt-7 rounded-xl bg-slate-50 p-4"><p className="text-sm font-bold text-slate-900">Key point</p><p className="mt-1 text-sm leading-6 text-slate-600">Follow your bank’s approved procedures and record decisions clearly.</p></div></Card></>}<div className="mt-7 flex justify-between"><Button variant="outline" disabled={moduleIndex === 0} onClick={() => setModuleIndex(moduleIndex - 1)}><ChevronLeft size={17} />Previous</Button><Button onClick={goNext}>{module.kind === 'assessment' ? 'Start assessment' : moduleIndex === course.modules.length - 2 ? 'Continue to assessment' : 'Complete and continue'}<ChevronRight size={17} /></Button></div></div></div></div>{drawer && <div className="fixed inset-0 z-50 bg-slate-950/40 lg:hidden"><aside className="ml-auto h-full w-[310px] bg-white p-4"><div className="mb-4 flex items-center justify-between"><p className="font-bold">Course content</p><button onClick={() => setDrawer(false)}><X /></button></div>{moduleNav}</aside></div>}</div>
}

function Assessment() {
  const { courseId } = useParams(); const tenant = useTenant(); const demo = useDemo(); const course = getTenantCourses(tenant.id).find((item) => item.id === courseId); const navigate = useNavigate(); const [index, setIndex] = useState(0); const [answers, setAnswers] = useState<Record<string, number>>({}); const [result, setResult] = useState<number | null>(null); if (!course?.quiz) return <Navigate to="/learn" replace />; const question = course.quiz[index]; const submit = () => { const correct = course.quiz!.filter((item) => answers[item.id] === item.correctIndex).length; const score = Math.round((correct / course.quiz!.length) * 100); demo.recordQuiz(course.id, score, course.passMark, course.modules.map((m) => m.id)); setResult(score); if (score >= course.passMark) toast.success('Course completed and certificate issued') }
  if (result !== null) { const passed = result >= course.passMark; return <div className="mx-auto max-w-3xl"><Card className="p-7 sm:p-10"><div className={cn('mx-auto grid h-16 w-16 place-items-center rounded-full', passed ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700')}>{passed ? <Award size={32} /> : <CircleAlert size={32} />}</div><div className="text-center"><p className="mt-5 text-sm font-bold uppercase tracking-wider text-slate-500">Assessment result</p><h1 className="mt-2 text-3xl font-bold">{passed ? 'Course completed' : 'Review and try again'}</h1><p className="mt-3 text-slate-600">You scored <strong>{result}%</strong>. The pass mark is {course.passMark}%.</p></div><div className="mt-8 space-y-3">{course.quiz.map((item, idx) => { const correct = answers[item.id] === item.correctIndex; return <div key={item.id} className="rounded-xl border border-slate-200 p-4"><div className="flex gap-3"><div className={cn('mt-0.5', correct ? 'text-emerald-600' : 'text-red-600')}>{correct ? <CheckCircle2 size={20} /> : <CircleAlert size={20} />}</div><div><p className="text-sm font-bold">{idx + 1}. {item.prompt}</p><p className="mt-1 text-xs leading-5 text-slate-500">{item.explanation}</p></div></div></div> })}</div><div className="mt-8 flex flex-col justify-center gap-3 sm:flex-row">{passed ? <><Button onClick={() => navigate('/learn/certificates')}><Award size={17} />View certificate</Button><Button variant="outline" onClick={() => navigate('/learn')}>Back to learning</Button></> : <><Button onClick={() => { setResult(null); setIndex(0); setAnswers({}) }}>Retry assessment</Button><Button variant="outline" onClick={() => navigate(`/learn/courses/${course.id}/player`)}>Review lessons</Button></>}</div></Card></div> }
  return <div className="mx-auto max-w-3xl"><PageTitle eyebrow="Knowledge check" title={course.title} description={`Question ${index + 1} of ${course.quiz.length} · ${course.passMark}% required to pass`} /><Progress value={((index + 1) / course.quiz.length) * 100} /><Card className="mt-6 p-6 sm:p-8"><h2 className="text-xl font-bold leading-7">{question.prompt}</h2><fieldset className="mt-6 space-y-3"><legend className="sr-only">Choose an answer</legend>{question.options.map((option, optionIndex) => <label key={option} className={cn('flex cursor-pointer items-start gap-3 rounded-xl border p-4 text-sm transition', answers[question.id] === optionIndex ? 'border-[var(--tenant-dark)] bg-[color-mix(in_srgb,var(--tenant-accent)_9%,white)]' : 'border-slate-200 hover:bg-slate-50')}><input type="radio" name={question.id} className="mt-0.5 accent-[var(--tenant-dark)]" checked={answers[question.id] === optionIndex} onChange={() => setAnswers({ ...answers, [question.id]: optionIndex })} /><span>{option}</span></label>)}</fieldset><div className="mt-8 flex justify-between"><Button variant="outline" disabled={index === 0} onClick={() => setIndex(index - 1)}><ChevronLeft size={17} />Back</Button>{index === course.quiz.length - 1 ? <Button disabled={answers[question.id] === undefined} onClick={submit}>Submit assessment</Button> : <Button disabled={answers[question.id] === undefined} onClick={() => setIndex(index + 1)}>Next question<ChevronRight size={17} /></Button>}</div></Card></div>
}

function CertificateListItem({ certificate, course, onOpen }: { certificate: Certificate; course: Course; onOpen: () => void }) {
  return <button type="button" onClick={onOpen} className="group grid w-full cursor-pointer gap-4 p-5 text-left transition-colors hover:bg-slate-50 focus-visible:relative focus-visible:z-10 sm:grid-cols-[48px_minmax(0,1fr)_24px] sm:items-center">
    <div className="grid h-12 w-12 place-items-center rounded-xl bg-amber-100 text-amber-700"><Award /></div>
    <div className="min-w-0"><Badge tone="green">Completed</Badge><h2 className="mt-2 font-bold text-slate-950">{course.title}</h2><p className="mt-1 text-xs text-slate-500">Issued {fmtDate(certificate.issuedAt)} · Score {certificate.score}% · {certificate.id}</p></div>
    <ChevronRight aria-hidden="true" className="text-[var(--tenant-dark)] transition-transform group-hover:translate-x-1" size={20} />
  </button>
}

function Certificates() {
  const demo = useDemo(); const tenant = useTenant(); const [selected, setSelected] = useState<string | null>(null); const list = demo.certificates.filter((certificate) => certificate.tenantId === tenant.id && certificate.userId === demo.currentUser?.id)
  return <><PageTitle eyebrow="Learner portal" title="Certificates" description="Your completed learning and assessment results." />{list.length ? <GroupedList>{list.map((certificate) => { const course = courses.find((item) => item.id === certificate.courseId)!; return <CertificateListItem key={certificate.id} certificate={certificate} course={course} onOpen={() => setSelected(certificate.id)} /> })}</GroupedList> : <EmptyState icon={Award} title="No certificates yet" body="Complete a course assessment to earn your first certificate." action={<Link to="/learn/catalogue"><Button>Browse courses</Button></Link>} />}{selected && <CertificateDialog id={selected} close={() => setSelected(null)} />}</>
}

function CertificateDialog({ id, close }: { id: string; close: () => void }) {
  const demo = useDemo(); const tenant = useTenant(); const certificate = demo.certificates.find((item) => item.id === id)!; const course = courses.find((item) => item.id === certificate.courseId)!
  return <Dialog open onOpenChange={(open) => !open && close()} title="Course certificate"><div className="print-card mt-5 border-[5px] border-double border-[var(--tenant-dark)] p-7 text-center"><Award className="mx-auto text-[var(--tenant-dark)]" size={42} /><p className="mt-4 text-xs font-bold uppercase tracking-[.25em] text-slate-500">Certificate of completion</p><h2 className="mt-5 text-2xl font-bold">{demo.currentUser?.name}</h2><p className="mt-3 text-sm text-slate-600">has successfully completed</p><p className="mt-3 text-xl font-bold text-[var(--tenant-dark)]">{course.title}</p><div className="mx-auto mt-6 h-px w-32 bg-slate-300" /><p className="mt-5 text-sm text-slate-600">{tenant.name} · {fmtDate(certificate.issuedAt)}</p><p className="mt-2 text-xs text-slate-400">Certificate ID {certificate.id} · Score {certificate.score}%</p></div><div className="no-print mt-5 flex justify-end"><Button onClick={() => window.print()}><Printer size={17} />Print or save</Button></div></Dialog>
}

function AdminOverview() {
  const tenant = useTenant(); const metric = metrics.find((item) => item.tenantId === tenant.id)!; const demo = useDemo(); const tenantAssignments = demo.assignments.filter((a) => a.tenantId === tenant.id)
  const cards = [{ label: 'Assigned employees', value: metric.assignedEmployees.toLocaleString(), change: 'Across required learning', icon: Users }, { label: 'Completion rate', value: `${metric.completionRate}%`, change: '+6 points this month', icon: CheckCircle2 }, { label: 'Overdue employees', value: metric.overdue.toLocaleString(), change: 'Require follow-up', icon: Clock3 }, { label: 'Average assessment', value: `${metric.averageScore}%`, change: 'Across completed courses', icon: ClipboardCheck }]
  return <><PageTitle eyebrow={`${tenant.name} · Demo data`} title="Learning overview" description="A current view of required learning and assessment performance." action={<Link to="/admin/reports"><Button><FileText size={17} />Open reports</Button></Link>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{cards.map((item) => <Card key={item.label} className="p-5"><div className="flex items-start justify-between"><p className="text-sm font-semibold text-slate-600">{item.label}</p><item.icon size={19} className="text-[var(--tenant-dark)]" /></div><p className="mt-4 text-3xl font-bold tracking-tight">{item.value}</p><p className="mt-2 text-xs text-slate-500">{item.change}</p></Card>)}</div><div className="mt-5 grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><Card className="p-5"><div><h2 className="font-bold">Completion trend</h2><p className="mt-1 text-xs text-slate-500">Required learning completed by month</p></div><div className="mt-5 h-72" aria-label="Completion trend chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={metric.trend}><defs><linearGradient id="completion" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor={tenant.accent} stopOpacity={0.28}/><stop offset="95%" stopColor={tenant.accent} stopOpacity={0}/></linearGradient></defs><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" /><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fontSize: 12 }} /><YAxis domain={[0, 100]} axisLine={false} tickLine={false} tick={{ fontSize: 12 }} /><Tooltip /><Area type="monotone" dataKey="completion" stroke={tenant.dark} fill="url(#completion)" strokeWidth={3} /></AreaChart></ResponsiveContainer></div><p className="sr-only">Completion increased from {metric.trend[0].completion}% in {metric.trend[0].month} to {metric.completionRate}% in September.</p></Card><Card className="p-5"><h2 className="font-bold">Completion by region</h2><p className="mt-1 text-xs text-slate-500">Current required learning</p><div className="mt-5 h-72"><ResponsiveContainer width="100%" height="100%"><BarChart data={metric.regions} layout="vertical" margin={{ left: 10 }}><XAxis type="number" domain={[0, 100]} hide /><YAxis type="category" dataKey="name" width={90} axisLine={false} tickLine={false} tick={{ fontSize: 11 }} /><Tooltip /><Bar dataKey="completion" fill={tenant.accent} radius={[0, 5, 5, 0]} barSize={18} /></BarChart></ResponsiveContainer></div></Card></div><Card className="mt-5 overflow-hidden"><div className="border-b border-slate-100 p-5"><h2 className="font-bold">Required course status</h2><p className="mt-1 text-xs text-slate-500">Active assignments in this bank workspace</p></div><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase tracking-wider text-slate-500"><tr><th className="px-5 py-3">Assignment</th><th className="px-5 py-3">Audience</th><th className="px-5 py-3">Employees</th><th className="px-5 py-3">Due date</th><th className="px-5 py-3">Status</th></tr></thead><tbody className="divide-y divide-slate-100">{tenantAssignments.map((assignment, index) => <tr key={assignment.id}><td className="px-5 py-4 font-semibold">{assignment.title}</td><td className="px-5 py-4 text-slate-600">{assignment.audienceValue ?? assignment.audienceType}</td><td className="px-5 py-4">{assignment.matchedEmployees.toLocaleString()}</td><td className="px-5 py-4">{fmtDate(assignment.dueDate)}</td><td className="px-5 py-4"><Badge tone={index === 2 ? 'amber' : 'green'}>{index === 2 ? 'Needs attention' : 'On track'}</Badge></td></tr>)}</tbody></table></div></Card></>
}

function Employees() {
  const tenant = useTenant(); const [search, setSearch] = useState(''); const [region, setRegion] = useState('All'); const [importOpen, setImportOpen] = useState(false); const [importState, setImportState] = useState<'idle' | 'valid' | 'error'>('idle'); const tenantUsers = users.filter((u) => u.tenantId === tenant.id && u.portalRole === 'learner'); const filtered = tenantUsers.filter((u) => `${u.name} ${u.staffId} ${u.jobTitle}`.toLowerCase().includes(search.toLowerCase()) && (region === 'All' || u.region === region)); const regions = Array.from(new Set(tenantUsers.map((u) => u.region)))
  return <><PageTitle eyebrow={`${tenant.name} · Demo data`} title="Employees" description="Employee attributes from the standard roster determine learning assignments and reporting access." action={<Button onClick={() => setImportOpen(true)}><Upload size={17} />Import employee roster</Button>} /><Card className="overflow-hidden"><div className="grid gap-3 border-b border-slate-100 p-4 md:grid-cols-[1fr_200px]"><label className="relative"><span className="sr-only">Search employees</span><Search className="absolute left-3 top-3 text-slate-400" size={19} /><input className={cn(inputClass, 'pl-10')} placeholder="Search name, staff ID, or role" value={search} onChange={(e) => setSearch(e.target.value)} /></label><select className={inputClass} aria-label="Filter by region" value={region} onChange={(e) => setRegion(e.target.value)}><option>All</option>{regions.map((item) => <option key={item}>{item}</option>)}</select></div>{filtered.length ? <div className="overflow-x-auto"><table className="w-full min-w-[980px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase tracking-wider text-slate-500"><tr><th className="px-5 py-3">Employee</th><th className="px-5 py-3">Staff ID</th><th className="px-5 py-3">Role and grade</th><th className="px-5 py-3">Branch</th><th className="px-5 py-3">Region</th><th className="px-5 py-3">Learning status</th><th className="px-5 py-3">Last active</th></tr></thead><tbody className="divide-y divide-slate-100">{filtered.map((user, index) => <tr key={user.id} className="hover:bg-slate-50/50"><td className="px-5 py-4"><p className="font-bold">{user.name}</p><p className="mt-1 text-xs text-slate-500">{user.email}</p></td><td className="px-5 py-4 text-slate-600">{user.staffId}</td><td className="px-5 py-4"><p>{user.jobTitle}</p><p className="mt-1 text-xs text-slate-500">{user.grade}</p></td><td className="px-5 py-4">{user.branch}</td><td className="px-5 py-4">{user.region}</td><td className="px-5 py-4"><Badge tone={index === 3 ? 'red' : index === 2 ? 'amber' : 'green'}>{index === 3 ? 'Overdue' : index === 2 ? 'In progress' : 'On track'}</Badge></td><td className="px-5 py-4 text-slate-500">{user.lastActive}</td></tr>)}</tbody></table></div> : <div className="p-8"><EmptyState icon={Users} title="No employees match these filters" body="Clear the search or select another region." action={<Button variant="outline" onClick={() => { setSearch(''); setRegion('All') }}>Clear filters</Button>} /></div>}</Card><Dialog open={importOpen} onOpenChange={setImportOpen} title="Import employee roster" description="Use one standard CSV structure instead of a custom HR system connection."><div className="mt-5 rounded-xl bg-slate-950 p-4 font-mono text-xs leading-6 text-slate-200">staff_id, full_name, email, role, grade,<br />branch, region, employment_status</div>{importState === 'valid' && <div className="mt-4 flex gap-3 rounded-xl bg-emerald-50 p-4 text-sm text-emerald-900"><CheckCircle2 size={20} /><div><p className="font-bold">Roster validated</p><p className="mt-1">248 records are ready to import. No errors found.</p></div></div>}{importState === 'error' && <div className="mt-4 flex gap-3 rounded-xl bg-red-50 p-4 text-sm text-red-900"><CircleAlert size={20} /><div><p className="font-bold">Validation failed</p><p className="mt-1">Three rows are missing a staff ID. Correct the file and try again.</p></div></div>}<div className="mt-5 rounded-xl border-2 border-dashed border-slate-300 p-7 text-center"><Upload className="mx-auto text-slate-400" /><p className="mt-3 text-sm font-bold">Choose a CSV file</p><p className="mt-1 text-xs text-slate-500">This prototype simulates file validation.</p><div className="mt-4 flex justify-center gap-2"><Button variant="outline" size="sm" onClick={() => setImportState('valid')}>Use valid sample</Button><Button variant="ghost" size="sm" onClick={() => setImportState('error')}>Show error</Button></div></div><div className="mt-5 flex justify-end gap-3"><Button variant="outline" onClick={() => setImportOpen(false)}>Cancel</Button><Button disabled={importState !== 'valid'} onClick={() => { toast.success('Employee roster imported'); setImportOpen(false); setImportState('idle') }}>Import 248 employees</Button></div></Dialog></>
}

function AssignmentListItem({ assignment, course }: { assignment: Assignment; course?: Course }) {
  return <div className="grid gap-4 p-5 md:grid-cols-[minmax(0,1fr)_140px_140px] md:items-center"><div><div className="flex flex-wrap gap-2"><Badge tone={assignment.required ? 'amber' : 'neutral'}>{assignment.required ? 'Required' : 'Optional'}</Badge><Badge>{course?.category}</Badge></div><h2 className="mt-3 font-bold text-slate-950">{assignment.title}</h2><p className="mt-1 text-sm text-slate-500">{assignment.audienceType}{assignment.audienceValue ? `: ${assignment.audienceValue}` : ''}</p></div><div><p className="text-xs text-slate-500">Matched employees</p><p className="mt-1 font-bold">{assignment.matchedEmployees.toLocaleString()}</p></div><div><p className="text-xs text-slate-500">Due date</p><p className="mt-1 font-bold">{fmtDate(assignment.dueDate)}</p></div></div>
}

function Assignments() {
  const tenant = useTenant(); const demo = useDemo(); const [open, setOpen] = useState(false); const assignments = demo.assignments.filter((a) => a.tenantId === tenant.id)
  return <><PageTitle eyebrow={`${tenant.name} · Demo data`} title="Learning assignments" description="Assign shared or bank-specific courses using standard employee attributes." action={<Button onClick={() => setOpen(true)}><Plus size={17} />Create assignment</Button>} /><GroupedList>{assignments.map((assignment) => <AssignmentListItem key={assignment.id} assignment={assignment} course={courses.find((course) => course.id === assignment.courseId)} />)}</GroupedList><AssignmentDialog open={open} close={() => setOpen(false)} /></>
}

function AssignmentDialog({ open, close }: { open: boolean; close: () => void }) {
  const tenant = useTenant(); const demo = useDemo(); const tenantCourses = getTenantCourses(tenant.id); const [courseId, setCourseId] = useState(tenantCourses[0].id); const [audienceType, setAudienceType] = useState<Assignment['audienceType']>('Everyone'); const [audienceValue, setAudienceValue] = useState(''); const [dueDate, setDueDate] = useState('2026-11-30'); const count = audienceType === 'Everyone' ? metrics.find((m) => m.tenantId === tenant.id)!.assignedEmployees : audienceType === 'Branch' ? 164 : audienceType === 'Region' ? 612 : audienceType === 'Grade' ? 438 : 286
  const submit = (e: FormEvent) => { e.preventDefault(); const course = tenantCourses.find((c) => c.id === courseId)!; demo.addAssignment({ courseId, title: course.title, required: true, dueDate, audienceType, audienceValue: audienceType === 'Everyone' ? undefined : audienceValue || (audienceType === 'Branch' ? 'Bole Branch' : audienceType === 'Region' ? 'Addis Ababa' : audienceType === 'Grade' ? 'Officer II' : 'Credit Analyst'), matchedEmployees: count }); toast.success('Learning assignment created'); close() }
  return <Dialog open={open} onOpenChange={(value) => !value && close()} title="Create learning assignment" description="Use employee attributes from the standard roster to define the audience."><form className="mt-5 space-y-4" onSubmit={submit}><label className="block"><span className="mb-2 block text-sm font-bold">Course</span><select className={inputClass} value={courseId} onChange={(e) => setCourseId(e.target.value)}>{tenantCourses.map((course) => <option key={course.id} value={course.id}>{course.title}</option>)}</select></label><div className="grid gap-4 sm:grid-cols-2"><label><span className="mb-2 block text-sm font-bold">Audience</span><select className={inputClass} value={audienceType} onChange={(e) => setAudienceType(e.target.value as Assignment['audienceType'])}>{['Everyone', 'Role', 'Grade', 'Branch', 'Region'].map((item) => <option key={item}>{item}</option>)}</select></label><label><span className="mb-2 block text-sm font-bold">Value</span><input className={inputClass} placeholder={audienceType === 'Everyone' ? 'All active employees' : `Enter ${audienceType.toLowerCase()}`} disabled={audienceType === 'Everyone'} value={audienceValue} onChange={(e) => setAudienceValue(e.target.value)} /></label></div><label className="block"><span className="mb-2 block text-sm font-bold">Due date</span><input type="date" min="2026-09-18" className={inputClass} value={dueDate} onChange={(e) => setDueDate(e.target.value)} /></label><div className="rounded-xl bg-[#f4f8f1] p-4"><p className="text-xs font-bold uppercase tracking-wider text-slate-500">Audience preview</p><p className="mt-2 text-2xl font-bold text-[var(--tenant-dark)]">{count.toLocaleString()} employees</p><p className="mt-1 text-xs text-slate-500">Matched from the current demo roster.</p></div><div className="flex justify-end gap-3 pt-2"><Button variant="outline" type="button" onClick={close}>Cancel</Button><Button type="submit">Create assignment</Button></div></form></Dialog>
}

function Reports() {
  const tenant = useTenant(); const metric = metrics.find((m) => m.tenantId === tenant.id)!; const demo = useDemo(); const [preview, setPreview] = useState(false); const [courseFilter, setCourseFilter] = useState('All courses'); const assignments = demo.assignments.filter((a) => a.tenantId === tenant.id)
  const exportCsv = () => { const lines = ['bank,assignment,audience,employees,due_date', ...assignments.map((a) => `"${tenant.name}","${a.title}","${a.audienceValue ?? a.audienceType}",${a.matchedEmployees},${a.dueDate}`)]; const blob = new Blob([lines.join('\n')], { type: 'text/csv' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `${tenant.id}-training-evidence.csv`; link.click(); URL.revokeObjectURL(url); toast.success('CSV evidence exported') }
  return <><PageTitle eyebrow={`${tenant.name} · Demo data`} title="Learning reports" description="Review completion and prepare a clear evidence pack for internal or regulatory reporting." action={<Button onClick={() => setPreview(true)}><FileText size={17} />Generate training evidence pack</Button>} /><Card className="mb-5 p-4"><div className="grid gap-3 md:grid-cols-[1fr_1fr_1fr_auto]"><select className={inputClass} value={courseFilter} onChange={(e) => setCourseFilter(e.target.value)}><option>All courses</option>{getTenantCourses(tenant.id).map((c) => <option key={c.id}>{c.title}</option>)}</select><select className={inputClass}><option>All regions</option>{metric.regions.map((r) => <option key={r.name}>{r.name}</option>)}</select><select className={inputClass}><option>All completion statuses</option><option>Completed</option><option>In progress</option><option>Overdue</option></select><Button variant="outline"><Filter size={17} />Apply</Button></div></Card><div className="grid gap-5 xl:grid-cols-[.7fr_1.3fr]"><Card className="p-5"><h2 className="font-bold">Assessment summary</h2><div className="mt-6 grid grid-cols-2 gap-4"><div className="rounded-xl bg-slate-50 p-4"><p className="text-xs text-slate-500">Average score</p><p className="mt-2 text-3xl font-bold">{metric.averageScore}%</p></div><div className="rounded-xl bg-slate-50 p-4"><p className="text-xs text-slate-500">First-time pass</p><p className="mt-2 text-3xl font-bold">76%</p></div></div><div className="mt-6 h-64"><ResponsiveContainer width="100%" height="100%"><BarChart data={metric.regions}><CartesianGrid strokeDasharray="3 3" vertical={false} /><XAxis dataKey="name" tick={{ fontSize: 10 }} axisLine={false} tickLine={false} /><YAxis domain={[0,100]} axisLine={false} tickLine={false} /><Tooltip /><Bar dataKey="completion" fill={tenant.dark} radius={[5,5,0,0]} /></BarChart></ResponsiveContainer></div></Card><Card className="overflow-hidden"><div className="flex items-center justify-between border-b border-slate-100 p-5"><div><h2 className="font-bold">Compliance completion</h2><p className="mt-1 text-xs text-slate-500">{courseFilter} · Current reporting period</p></div><Button variant="outline" size="sm" onClick={exportCsv}><Download size={16} />Export CSV</Button></div><div className="overflow-x-auto"><table className="w-full min-w-[650px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase tracking-wider text-slate-500"><tr><th className="px-5 py-3">Region</th><th className="px-5 py-3">Assigned</th><th className="px-5 py-3">Completed</th><th className="px-5 py-3">Completion</th><th className="px-5 py-3">Status</th></tr></thead><tbody className="divide-y divide-slate-100">{metric.regions.map((region, index) => { const assigned = [840, 510, 690, 440][index] ?? 300; const completed = Math.round(assigned * region.completion / 100); return <tr key={region.name}><td className="px-5 py-4 font-bold">{region.name}</td><td className="px-5 py-4">{assigned}</td><td className="px-5 py-4">{completed}</td><td className="px-5 py-4"><div className="flex items-center gap-3"><Progress value={region.completion} className="w-20" />{region.completion}%</div></td><td className="px-5 py-4"><Badge tone={region.completion >= 70 ? 'green' : 'amber'}>{region.completion >= 70 ? 'On track' : 'Follow up'}</Badge></td></tr> })}</tbody></table></div></Card></div><EvidenceDialog open={preview} close={() => setPreview(false)} /></>
}

function EvidenceDialog({ open, close }: { open: boolean; close: () => void }) {
  const tenant = useTenant(); const metric = metrics.find((m) => m.tenantId === tenant.id)!; const demo = useDemo(); const assignments = demo.assignments.filter((a) => a.tenantId === tenant.id)
  return <Dialog open={open} onOpenChange={(value) => !value && close()} title="Training evidence pack" description="Printable preview for the current reporting period."><div className="print-card mt-5 border border-slate-200 p-6"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-wider text-[var(--tenant-dark)]">Training evidence report</p><h2 className="mt-2 text-2xl font-bold">{tenant.name}</h2><p className="mt-1 text-sm text-slate-500">Reporting period: January–September 2026</p></div><Badge tone="amber">Demo data</Badge></div><div className="mt-6 grid grid-cols-2 gap-3 sm:grid-cols-4">{[['Assigned', metric.assignedEmployees.toLocaleString()], ['Completed', Math.round(metric.assignedEmployees * metric.completionRate / 100).toLocaleString()], ['Completion', `${metric.completionRate}%`], ['Avg. score', `${metric.averageScore}%`]].map(([label, value]) => <div key={label} className="rounded-lg bg-slate-50 p-3"><p className="text-[10px] uppercase tracking-wider text-slate-500">{label}</p><p className="mt-1 font-bold">{value}</p></div>)}</div><h3 className="mt-6 text-sm font-bold">Included learning</h3><div className="mt-2 divide-y divide-slate-100 border-y border-slate-100">{assignments.map((a) => <div key={a.id} className="flex justify-between gap-4 py-3 text-xs"><span className="font-semibold">{a.title}</span><span className="text-slate-500">{a.matchedEmployees.toLocaleString()} assigned</span></div>)}</div><h3 className="mt-6 text-sm font-bold">Completion by region</h3><div className="mt-3 space-y-2">{metric.regions.map((r) => <div key={r.name} className="flex items-center gap-3 text-xs"><span className="w-24">{r.name}</span><Progress value={r.completion} className="flex-1" /><strong>{r.completion}%</strong></div>)}</div><p className="mt-6 border-t border-slate-200 pt-4 text-[10px] leading-4 text-slate-400">Generated 17 September 2026. Prototype evidence only. This preview does not submit information to a regulator.</p></div><div className="no-print mt-5 flex justify-end"><Button onClick={() => window.print()}><Printer size={17} />Print or save report</Button></div></Dialog>
}

function EmptyState({ icon: Icon, title, body, action }: { icon: typeof Search; title: string; body: string; action?: ReactNode }) { return <Card className="grid min-h-72 place-items-center p-8 text-center"><div><div className="mx-auto grid h-12 w-12 place-items-center rounded-xl bg-slate-100 text-slate-500"><Icon /></div><h2 className="mt-4 font-bold text-slate-900">{title}</h2><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-slate-500">{body}</p>{action && <div className="mt-5">{action}</div>}</div></Card> }

function RoleRoute({ role, children }: { role: DemoRole; children: ReactNode }) { const demo = useDemo(); return demo.role === role ? <>{children}</> : <Navigate to={demo.role === 'learner' ? '/learn' : '/admin'} replace /> }

export function App() {
  return <Routes>
    <Route path="/" element={<SignIn />} />
    <Route path="/learn" element={<Protected><RoleRoute role="learner"><LearnerHome /></RoleRoute></Protected>} />
    <Route path="/learn/my-learning" element={<Protected><RoleRoute role="learner"><MyLearning /></RoleRoute></Protected>} />
    <Route path="/learn/catalogue" element={<Protected><RoleRoute role="learner"><Catalogue /></RoleRoute></Protected>} />
    <Route path="/learn/courses/:courseId" element={<Protected><RoleRoute role="learner"><CourseDetails /></RoleRoute></Protected>} />
    <Route path="/learn/courses/:courseId/player" element={<Protected><RoleRoute role="learner"><CoursePlayer /></RoleRoute></Protected>} />
    <Route path="/learn/courses/:courseId/assessment" element={<Protected><RoleRoute role="learner"><Assessment /></RoleRoute></Protected>} />
    <Route path="/learn/certificates" element={<Protected><RoleRoute role="learner"><Certificates /></RoleRoute></Protected>} />
    <Route path="/admin" element={<Protected><RoleRoute role="admin"><AdminOverview /></RoleRoute></Protected>} />
    <Route path="/admin/employees" element={<Protected><RoleRoute role="admin"><Employees /></RoleRoute></Protected>} />
    <Route path="/admin/assignments" element={<Protected><RoleRoute role="admin"><Assignments /></RoleRoute></Protected>} />
    <Route path="/admin/reports" element={<Protected><RoleRoute role="admin"><Reports /></RoleRoute></Protected>} />
    <Route path="*" element={<Navigate to="/" replace />} />
  </Routes>
}
